DROP TABLE IF EXISTS `places`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `places` (
  `PlaceID` int NOT NULL AUTO_INCREMENT,
  `Name` varchar(200) DEFAULT NULL COMMENT 'Name of the place',
  `CityID` int DEFAULT NULL COMMENT 'Foreign key referencing the city this place is in',
  `PlaceTypeID` int DEFAULT NULL COMMENT 'Foreign key referencing the type of this place',
  `SignificanceID` int DEFAULT NULL COMMENT 'Foreign key referencing the significance of this place',
  `EstablishmentYear` varchar(20) DEFAULT NULL COMMENT 'Year the place was established or opened',
  `TimeNeededToVisit` decimal(4,1) DEFAULT NULL COMMENT 'Recommended time to visit (e.g., 2.5 hours)',
  `GoogleReviewRating` decimal(3,1) DEFAULT NULL COMMENT 'Average Google review rating for this place',
  `EntranceFeeINR` int DEFAULT NULL,
  `AirportWithin50km` tinyint DEFAULT NULL COMMENT 'Is there an airport within 50 km (TRUE/FALSE)',
  `WeeklyOff` varchar(50) DEFAULT NULL COMMENT 'Days of the week when the place is closed to visitors (e.g., Monday, Sunday)',
  `DSLRAllowed` tinyint DEFAULT NULL COMMENT 'Whether DSLR cameras are allowed (TRUE/FALSE)',
  `NumberOfGoogleReviews` decimal(6,2) DEFAULT NULL,
  `BestTimeToVisit` varchar(100) DEFAULT NULL COMMENT 'Best season or months to visit the place',
  PRIMARY KEY (`PlaceID`),
  KEY `places_ibfk_1` (`CityID`),
  KEY `places_ibfk_2` (`PlaceTypeID`),
  KEY `places_ibfk_3` (`SignificanceID`),
  CONSTRAINT `places_ibfk_1` FOREIGN KEY (`CityID`) REFERENCES `cities` (`CityID`),
  CONSTRAINT `places_ibfk_2` FOREIGN KEY (`PlaceTypeID`) REFERENCES `placetypes` (`PlaceTypeID`),
  CONSTRAINT `places_ibfk_3` FOREIGN KEY (`SignificanceID`) REFERENCES `significances` (`SignificanceID`)
) ENGINE=InnoDB AUTO_INCREMENT=512 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

